{"filename":"models.py","content":"import os
import sqlite3
from flask import current_app, g

SCHEMA = """
CREATE TABLE IF NOT EXISTS tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    description TEXT,
    status TEXT NOT NULL DEFAULT 'pending',
    priority TEXT NOT NULL DEFAULT 'medium',
    due_date TEXT,
    created_at TEXT NOT NULL DEFAULT (datetime('now', 'localtime'))
);

CREATE INDEX IF NOT EXISTS idx_tasks_status ON tasks(status);
CREATE INDEX IF NOT EXISTS idx_tasks_priority ON tasks(priority);
CREATE INDEX IF NOT EXISTS idx_tasks_due_date ON tasks(due_date);
"""


def get_db():
    """Get or open a connection to the SQLite database for the current request context."""
    if "db" not in g:
        db_path = current_app.config.get("DATABASE", "taskflow.db")
        g.db = sqlite3.connect(
            db_path,
            detect_types=sqlite3.PARSE_DECLTYPES | sqlite3.PARSE_COLNAMES
        )
        g.db.row_factory = sqlite3.Row
        g.db.execute("PRAGMA foreign_keys = ON;")
    return g.db


def close_db(e=None):
    """Close the database connection at the end of the request."""
    db = g.pop("db", None)
    if db is not None:
        db.close()


def init_db():
    """Initialize database tables and indices according to schema without seeding data."""
    db = get_db()
    db.executescript(SCHEMA)
    db.commit()


def init_app(app):
    """Register database functions and lifecycle cleanup with the Flask application."""
    if "DATABASE" not in app.config:
        app.config["DATABASE"] = os.path.join(app.instance_path, "taskflow.db")
        try:
            os.makedirs(app.instance_path, exist_ok=True)
        except OSError:
            pass

    app.teardown_appcontext(close_db)

    with app.app_context():
        init_db()


def task_to_dict(row):
    """Convert a sqlite3.Row representing a Task into a dictionary."""
    if row is None:
        return None
    return {
        "id": row["id"],
        "title": row["title"],
        "description": row["description"] if row["description"] is not None else "",
        "status": row["status"],
        "priority": row["priority"],
        "due_date": row["due_date"] if row["due_date"] is not None else "",
        "created_at": row["created_at"]
    }
